-- EXCEL EFFICIENCY TEST 2 (version 1866e1f0): the paper solution, text only, one per question. Students see it on
-- their result page once the result is shown (migration 202610261000). Safe to run twice.
begin;

update public.excel_efficiency_questions as q
set solution = s.solution, solution_image = null
from (values
 (1, E'1. Click **A1** (the merged "Result" heading).\n2. HOME → **Format Painter** — double-click it so it stays on for more than one paste.\n3. Click **A19**, then **A21**, then **A23** (each one is a merged cell A19:J20, A21:J22, A23:J24).\n4. Press **Esc** (or click Format Painter again) to switch it off.\n\nChecked: A19, A21 and A23 have A1''s formatting — bold, 24 pt, dark red fill.'),
 (2, E'1. Select **A26:J37** (type A26:J37 in the Name Box and press Enter).\n2. HOME → **Middle Align** and **Center**.\n3. HOME → **Font Color ▾** → **Red** (Standard Colors).\n4. HOME → Font Size box → type **11.5** → Enter.\n5. HOME → **Fill Color ▾** → **Light Green** (Standard Colors).\n\nChecked on B26:J37: middle and centre, red font, 11.5 pt, light green fill. (Column A of this range gets A4''s formatting later in Q6, so it is not checked here.)'),
 (3, E'1. Select **A25:J37**.\n2. HOME → **Borders ▾** (in the Font group) → **Thick Box Border**.\n\nChecked: a thick border on the top, right and bottom edges of the table. (Q6 later pastes A4''s formatting onto A26:A37, which replaces the left edge there, exactly as in Excel — so the left edge is not checked.)'),
 (4, E'1. Select the **complete sheet**: click the box at the top-left corner, before column A and above row 1 (or press Ctrl+A).\n2. HOME → **Format ▾** (in the Cells group) → **AutoFit Row Height**.\n3. HOME → **Format ▾** → **AutoFit Column Width**.\n\nChecked: AutoFit Row Height on rows 1–44 and AutoFit Column Width on columns A–M (the used part of the sheet).'),
 (5, E'1. Select **A25:J25**.\n2. HOME → **Center** and **Middle Align**.\n3. HOME → **Underline ▾** → **Double Underline**.\n4. HOME → **Fill Color ▾** → **Dark Red** (Standard Colors).\n5. HOME → **Font Color ▾** → **White**.\n\nChecked: A25:J25 double underlined, dark red fill, white font.'),
 (6, E'1. Select **A4:A15** and press **Ctrl+C** (HOME → Copy).\n2. Click **A26**.\n3. HOME → **Paste ▾** → **Paste Special…** → **Formats** → OK. (Format Painter also works: select A4:A15, click Format Painter, then select A26:A37.)\n\nChecked: A26:A37 has the same formatting as A4:A15 (font, colours, fill, borders, alignment), after Q2''s formatting was applied to the range.'),
 (7, E'1. Select **A40:A44**.\n2. HOME → **Clear ▾** (in the Editing group) → **Clear Formats**. The text stays; only its formatting is removed.\n3. Select **A40:I44**.\n4. Press **Ctrl+1** (Format Cells) → **Alignment** tab → Horizontal: **Left (Indent)** → Indent: **10** → OK.\n\nChecked: (a) A40:A44 has no formatting left (not bold, not underlined, normal font colour, Calibri 11); (b) A40:I44 left aligned with indent 10.'),
 (8, E'1. Click **M3**, type **Sunday** and press Enter.\n2. Click M3 again. Point at the small square at its bottom-right corner (the fill handle) — the pointer becomes a thin black +.\n3. Drag it down to **M9** and release.\n\nExcel fills Monday, Tuesday … Saturday by itself. Checked: M4:M9 = Monday to Saturday (capital or small letters both count).'),
 (9, E'1. Click **M13**, type **January** and press Enter.\n2. Click M13 again and drag its fill handle (the small square at the bottom-right corner) down to **M24**.\n\nExcel fills February … December by itself. Checked: M13:M24 = January to December.'),
 (10, E'**Total**\n1. Click **G4** → HOME → **AutoSum**. The cell shows **=SUM(B4:F4)** with B4:F4 selected — press **Enter**.\n2. Fill it down: select **G4:G15** and press **Ctrl+D** (or double-click G4''s fill handle). Each row gets its own total, e.g. G5 = SUM(B5:F5).\n\n**Percentage** (5 subjects × 100 = 500 marks)\n3. Click **I4**, type **=G4/500** and press Enter (it shows 0.498).\n4. Select **I4:I15** and press **Ctrl+D**.\n5. Keep I4:I15 selected → HOME → **%** (Percent Style). I4 now shows **50%**. Do not add decimal places.\n\nChecked: the total of each student in G4:G15 and the percentage in I4:I15 in Percent Style (Rajnish 249 → 50%).')
) as s(question_number, solution)
where q.version_id = '1866e1f0-35d3-45a1-9303-53e8c7a1e0cf' and q.question_number = s.question_number;

commit;
